    ok = True
    for n in NS:
        STn, m, B, Bd, N, vac = _system(n)
        K3 = _scl(F(1, 2), GA.sub(N, GA.sc(n)))
        c = GA.sub(m(B, Bd), m(Bd, B))
        ok = ok and GA.eq(GA.sub(m(K3, Bd), m(Bd, K3)), Bd) and GA.eq(GA.sub(m(K3, B), m(B, K3)), GA.neg(B))
        ok = ok and GA.eq(c, _scl(F(-2), K3))
    GA.check("(B*, B, K3) close as su(2): [K3, B*] = B*, [K3, B] = -B, [B, B*] = -2 K3", ok)
    return ok


def check_finite_ladder():
    premise("field-theory.imported-tower-limit")
    ok = True
    for n in NS:
        STn, m, B, Bd, N, vac = _system(n)
        c = GA.sub(m(B, Bd), m(Bd, B))
        st = vac
        for k in range(n + 1):
            ok = ok and not GA.is_zero(st) and GA.eq(m(c, st), _scl(F(n - 2 * k), st))
            st = m(Bd, st)
        ok = ok and GA.is_zero(st)
    GA.check("[B, B*] = n - 2k on k-pair states, (B*)^(n+1) vacuum = 0: n + 1 states", ok)
    return ok

field-theory.imported-statistics-no-go-p:
"""field-theory.imported-statistics-no-go-palatial-algebra: exact checks of the finite core.

hbar is a fixed nonzero rational (the statements are homogeneous in it).
(1) No finite-dimensional home. In Cl(2,4) (dimension 64) the left-regular trace of every basis blade
    is 64 for the unit and 0 otherwise, and the scalar part of [A, B] vanishes for all 4096 ordered
    blade pairs; by bilinearity no x, y in Cl(2,4) or its complexification satisfy [x, y] = hbar.
    The same trace obstruction in a matrix representation: the polynomial realisation truncated to
    degree <= d (d = 1..6) gives [Z, Zbar] = hbar diag(1, ..., 1, -d), of trace 0, never hbar times
    the identity; the failure sits at the top degree.
(2) The polynomial realisation. On polynomials in Z^1..Z^4 with Zbar_b = -hbar d/dZ^b,
    [Z^a, Zbar_b] p = hbar delta_ab p for all 16 pairs (a, b) and four sample polynomials, while the
    Z^a commute among themselves and so do the Zbar_b.
Not checked: the bounded infinite-dimensional case (Wielandt-Wintner), which has no finite core
beyond the trace argument in (1).
"""
from fractions import Fraction as F

import GA
from tp_premise import premise

HBAR = F(3, 7)
SQ = GA.sig(2, 4)
NV = 4
POLYS = (
    {(0, 0, 0, 0): F(1)},
    {(2, 1, 0, 0): F(3), (0, 0, 1, 3): F(-2), (1, 0, 0, 0): F(1, 2)},
    {(1, 1, 1, 1): F(5), (0, 4, 0, 0): F(1)},
    {(3, 0, 2, 0): F(-1, 3), (0, 0, 0, 1): F(7), (1, 2, 0, 0): F(2)},
)


def padd(*ps):
    out = {}
    for p in ps:
        for e, c in p.items():
            out[e] = out.get(e, F(0)) + c
    return {e: c for e, c in out.items() if c != 0}


def zmul(a, p):
    return {tuple(e[i] + (i == a) for i in range(NV)): c for e, c in p.items()}


def zbar(b, p):
    out = {}
    for e, c in p.items():
        if e[b]:
            ne = tuple(e[i] - (i == b) for i in range(NV))
            out[ne] = out.get(ne, F(0)) - HBAR * e[b] * c
    return {e: c for e, c in out.items() if c != 0}


def scal(c, p):
    return {e: c * v for e, v in p.items() if c * v != 0}


def check_no_finite_dimensional_representation():
    premise("correspondence.statistics-no-go")
    ok = True
    blades = GA.all_blades(6)
    ok = ok and len(blades) == 64
    for b in blades:
        tr = sum((GA.blade_mul(b, c, SQ)[0] for c in blades if GA.blade_mul(b, c, SQ)[1] == c), F(0))
        ok = ok and tr == (64 if b == () else 0)
    for a in blades:
        for b in blades:
            ca, pa = GA.blade_mul(a, b, SQ)
            cb, pb = GA.blade_mul(b, a, SQ)
            s = (ca if pa == () else 0) - (cb if pb == () else 0)
            ok = ok and s == 0
    for d in range(1, 7):
        n = d + 1
        Z = [[F(1) if i == j + 1 else F(0) for j in range(n)] for i in range(n)]
        Zb = [[-HBAR * j if i == j - 1 else F(0) for j in range(n)] for i in range(n)]
        Cm = [[x - y for x, y in zip(r1, r2)] for r1, r2 in zip(GA.mat_mul(Z, Zb), GA.mat_mul(Zb, Z))]
        want = [[(HBAR if i < d else -d * HBAR) if i == j else F(0) for j in range(n)] for i in range(n)]
        ok = ok and Cm == want and sum(Cm[i][i] for i in range(n)) == 0
    GA.check("trace of every commutator vanishes in Cl(2,4) and in truncations: [x, y] = hbar has no solution", ok)
    return ok


def check_polynomial_realisation():
    premise("correspondence.symmetrised-quadratics-palatial-algebra")
    ok = True
    for p in POLYS:
        for a in range(NV):
            for b in range(NV):
                c = padd(zmul(a, zbar(b, p)), scal(F(-1), zbar(b, zmul(a, p))))
                ok = ok and c == (scal(HBAR, p) if a == b else {})
                ok = ok and padd(zmul(a, zmul(b, p)), scal(F(-1), zmul(b, zmul(a, p)))) == {}
                ok = ok and padd(zbar(a, zbar(b, p)), scal(F(-1), zbar(b, zbar(a, p)))) == {}
    GA.check("on polynomials, Zbar_b = -hbar d/dZ^b gives [Z^a, Zbar_b] = hbar delta_ab", ok)
    return ok

field-theory.path-integral-inside-tower:
"""field-theory.path-integral-inside-tower: exact checks.

Grassmann variables: the blade engine with all squares 0 (exterior algebra); the Berezin integral
over prod_m dpsibar_m dpsi_m is (-1)^(M) times the top coefficient (int dpsibar dpsi e^{-a psibar
psi} = a). The sliced action S = sum_m psibar_m psi_m - t psibar_m psi_{m-1}, psi_0 = eta psi_M,
t = 1 - delta (H = N on one mode, delta = beta eps/M), eta = -1 (antiperiodic) or +1 (periodic).
(1) Grassmann variables are further rungs: in the tower (planes of squares +1, -1, premise
tower-limit) the creation vectors of four further rungs square to 0, anticommute pairwise and with
the physical pair, and have a nonzero top product; with the rung vectors as Grassmann generators and
the Berezin integral realised as w...w x P0 (P0 the rungs' vacuum projector), the M = 2 integrals are
the abstract ones (one overall sign fixed once).
(2) Exact slicing: Berezin(exp(-S)) = det(A) = 1 - eta t^M = Tr(1 - delta N)^M (eta = -1) and
Tr Gamma (1 - delta N)^M (eta = +1), M = 1..5, delta = 1/3, 2/7, 5/4; two modes factorise.
(3) The limit: the occupancy at slicing M is t^M/(1 + t^M); with x = beta eps = 1, e^{-1} is
bracketed by alternating partial sums and (1 - 1/M)^M lies in [lo (1 - 1/M), hi] at M = 100, 1000
(e^{-x}(1 - x^2/M) <= (1 - x/M)^M <= e^{-x}), so Tr(1 - delta N)^M -> 1 + e^{-1} = Tr e^{-beta H}
and the occupancy -> 1/(e + 1), Fermi-Dirac, with an interval of width < 1/M around it.
(4) Two-point function: <psi_m psibar_n> from the Berezin integral depends on m - n only, equals the
time-ordered operator function (Gamma inserted for the periodic closure), and G(j - M) = eta G(j):
antiperiodic for the trace, periodic for the supertrace, at every slicing M = 2, 3, 4.
The period (the identification of the Euclidean circle) is imported and not checked.
"""
from fractions import Fraction as F

import GA
from GA import mul, add, neg, sc, gen, eq, is_zero, anticommutes
from tp_premise import premise

ST = tuple([1, -1] * 5)
GR = tuple([0] * 40)
DELTAS = [F(1, 3), F(2, 7), F(5, 4)]


def scl(c, x):
    return {b: c * v for b, v in x.items() if c * v != 0}


def pair(e, f):
    return (add(scl(F(1, 2), gen(e)), scl(F(1, 2), gen(f))),
            add(scl(F(1, 2), gen(e)), scl(F(-1, 2), gen(f))))


def exp_nil(X, s, nmax):
    out, term = sc(1), sc(1)
    for n in range(1, nmax + 1):
        term = scl(F(1, n), mul(term, X, s))
        if not term:
            break
        out = add(out, term)
    return out


def action(M, t, eta, base=0):
    Sx = {}
    for m in range(1, M + 1):
        pb = base + 2 * (m - 1)
        Sx = add(Sx, {(pb, pb + 1): F(1)})
        prev, c = (pb - 1, -t) if m >= 2 else (base + 2 * (M - 1) + 1, -t * eta)
        Sx = add(Sx, scl(c, mul(gen(pb), gen(prev), GR)))
    return Sx


def berezin(x, ngen):
    return F((-1) ** (ngen // 2)) * x.get(tuple(range(ngen)), F(0))


def mid(n):
    return [[F(1) if i == j else F(0) for j in range(n)] for i in range(n)]


def mmul(A, B):
    return [[sum((A[i][t] * B[t][j] for t in range(len(B))), F(0)) for j in range(len(B[0]))]
            for i in range(len(A))]


def mtrace(A):
    return sum((A[i][i] for i in range(len(A))), F(0))


def mdet(A):
    M = [list(r) for r in A]
    n, det = len(M), F(1)
    for c in range(n):
        piv = next((r for r in range(c, n) if M[r][c] != 0), None)
        if piv is None:
            return F(0)
        if piv != c:
            M[c], M[piv] = M[piv], M[c]
            det = -det
        det *= M[c][c]
        for r in range(c + 1, n):
            f = M[r][c] / M[c][c]
            M[r] = [a - f * b for a, b in zip(M[r], M[c])]
    return det


def diff_matrix(M, t, eta):
    A = mid(M)
    for m in range(1, M):
        A[m][m - 1] = -t
    A[0][M - 1] += -t * eta
    return A


def tmat_power(t, M):
    T, out = [[F(1), F(0)], [F(0), t]], mid(2)
    for _ in range(M):
        out = mmul(out, T)
    return out


def check_grassmann_variables_are_rungs():
    premise("field-theory.imported-tower-limit")
    vp, wp = pair(0, 1)
    rungs = [pair(2 * j, 2 * j + 1) for j in range(1, 5)]
    us = [r[0] for r in rungs]
    ws = [r[1] for r in rungs]
    assert all(is_zero(mul(u, u, ST)) for u in us)
    assert all(anticommutes(us[i], us[j], ST) for i in range(4) for j in range(i + 1, 4))
    assert all(anticommutes(u, x, ST) for u in us for x in (vp, wp))
    top = sc(1)
    for u in us:
        top = mul(top, u, ST)
    assert not is_zero(top) and len(next(iter(top))) >= 4
    P0 = sc(1)
    for j in range(4):
        P0 = mul(P0, mul(ws[j], us[j], ST), ST)

    def tower_berezin(x):
        y = x
        for j in range(4):
            y = mul(ws[j], y, ST)
        y = mul(y, P0, ST)
        b0, c0 = next(iter(P0.items()))
        c = y.get(b0, F(0)) / c0
        assert eq(y, scl(c, P0))
        return c

    def to_tower(x):
        out = {}
        for b, c in x.items():
            term = sc(c)
            for g in b:
                term = mul(term, us[g], ST)
            out = add(out, term)
        return out

    sgn = tower_berezin(to_tower(exp_nil(neg(action(2, F(1, 2), 0)), GR, 4)))
    sgn = sgn / berezin(exp_nil(neg(action(2, F(1, 2), 0)), GR, 4), 4)
    assert sgn in (F(1), F(-1))
    for t in (F(2, 3), F(-1, 4)):
        for eta in (-1, 1):
            xx = exp_nil(neg(action(2, t, eta)), GR, 4)
            assert tower_berezin(to_tower(xx)) == sgn * (1 - eta * t ** 2)


def check_exact_slicing_is_trace():
    Gam = [[F(1), F(0)], [F(0), F(-1)]]
    cases = 0
    for M in range(1, 6):
        for delta in DELTAS:
            t = 1 - delta
            for eta in (-1, 1):
                Z = berezin(exp_nil(neg(action(M, t, eta)), GR, 2 * M), 2 * M)
                TM = tmat_power(t, M)
                trace = mtrace(TM) if eta == -1 else mtrace(mmul(Gam, TM))
                assert Z == mdet(diff_matrix(M, t, eta)) == 1 - eta * t ** M == trace
                cases += 1
    assert cases == 30
    for M in (2, 3):
        t1, t2 = F(2, 3), F(5, 7)
        S12 = add(action(M, t1, -1, 0), action(M, t2, -1, 2 * M))
        assert berezin(exp_nil(neg(S12), GR, 4 * M), 4 * M) == (1 + t1 ** M) * (1 + t2 ** M)


def check_continuum_limit_gibbs_and_fermi_dirac():
    fact = [1]
    for k in range(1, 20):
        fact.append(fact[-1] * k)
    lo = sum((F((-1) ** k, fact[k]) for k in range(0, 14)), F(0))       # ends on a negative term
    hi = sum((F((-1) ** k, fact[k]) for k in range(0, 13)), F(0))
    assert lo < hi and hi - lo < F(1, 10 ** 9)
    Nn = [[F(0), F(0)], [F(0), F(1)]]
    for M in (1, 2, 5, 10):
        t = 1 - F(1, M)
        TM = tmat_power(t, M)
        assert mtrace(mmul(Nn, TM)) / mtrace(TM) == t ** M / (1 + t ** M)
    fd = lambda y: y / (1 + y)
    for M in (100, 1000):
        tM = (1 - F(1, M)) ** M
        assert lo * (1 - F(1, M)) <= tM <= hi
        # Tr(1 - delta N)^M = 1 + t^M within [1 + lo(1 - 1/M), 1 + hi] around 1 + e^{-1}
        nM = fd(tM)
        assert fd(lo * (1 - F(1, M))) <= nM <= fd(hi) and fd(hi) - fd(lo * (1 - F(1, M))) < F(1, M)
    # the Fermi-Dirac value 1/(e + 1) = e^{-1}/(1 + e^{-1}) lies in [fd(lo), fd(hi)]
    assert fd(lo) < fd(hi) and fd(lo) > F(26, 100) and fd(hi) < F(27, 100)


def check_two_point_function_matsubara():
    a = [[F(0), F(1)], [F(0), F(0)]]
    ad = [[F(0), F(0)], [F(1), F(0)]]
    for M in (2, 3, 4):
        for t in (F(2, 3), F(-1, 4)):
            for eta in (-1, 1):
                ex = exp_nil(neg(action(M, t, eta)), GR, 2 * M)
                Z = berezin(ex, 2 * M)
                Gam = [[F(1), F(0)], [F(0), F(-1)]] if eta == 1 else mid(2)
                Tp = [tmat_power(t, j) for j in range(M + 1)]
                Zop = mtrace(mmul(Gam, Tp[M]))
                Gby = {}
                for m in range(1, M + 1):
                    for n in range(1, M + 1):
                        ins = mul(gen(2 * (m - 1) + 1), gen(2 * (n - 1)), GR)
                        G = berezin(mul(ins, ex, GR), 2 * M) / Z
                        j = m - n
                        if j >= 0:
                            op = mtrace(mmul(Gam, mmul(Tp[M - j], mmul(a, mmul(Tp[j], ad))))) / Zop
                        else:
                            op = -mtrace(mmul(Gam, mmul(Tp[M + j], mmul(ad, mmul(Tp[-j], a))))) / Zop
                        assert G == op
                        if j in Gby:
                            assert Gby[j] == G
                        Gby[j] = G
                for j in range(1, M):
                    assert Gby[j - M] == eta * Gby[j] and Gby[j] != 0

field-theory.second-quantisation:
"""field-theory.second-quantisation: exact checks in the single algebra (blade engine, Fraction).

Ground Cl(1,3) (gamma_0..3, squares 1, -1, -1, -1) plus 12 tower planes (generators of square +1, -1;
v = (e + f)/2 creates, w = (e - f)/2 annihilates; the planes give the CAR, premise tower-limit).
Complex numbers enter only as rational points of the unit circle (GA.QI) used as real coefficients
with i acting as right I sigma_3 = gamma_2 gamma_1 on spinor values. Null momenta k = (1,0,0,1),
(5,3,4,0), (3,2,1,2); chi_eps(phi) = (phi - eps I4 phi I sigma_3)/2; proj keeps span{1, I4} of the
ground (tower parts carried along).
(1) Lambda(k) = k gamma_0/(2 k_0) is idempotent, self-adjoint for alpha(phi, u) = <phi^dagger u>_0,
complex linear, the identity on ker k, of rank 4 with range ker k: the orthogonal projector onto
ker k; it commutes with chi_+-, and f <f, phi> = alpha(f, f) Lambda(k) chi_eps(phi) (completeness).
(2) The field Psi = sum_j [f_j p_j w + f_j conj(p_j) v] (one chirality): the anticommutator
{Psi(x; phi1), Psi(y; phi2)^*}, computed in the algebra, has no tower part and equals
<phi1, sum_j 2 alpha_j cos(k_j.(x - y)) Lambda(k_j) chi phi2> with i -> eps I4, for eps = +1 and -1;
2 k_0 Lambda(k) = k gamma_0, the GA form of chi (nabla D) gamma_0 (the continuum limit is imported).
Without the projection the anticommutator has other ground components (control).
(3) The pairing <phi, u> is the projection of phi^dagger u onto span{1, I4} for chiral u (and fails
for a non-chiral u, control); proj(Psi^* M Psi) for the particle field equals
sum_cd <u_c, M u_d> a_c^* a_d for M = 1, gamma_01, gamma_12 (d Gamma(M)); with antiparticle terms
present a c-number sum_j alpha(f_j, f_j) appears (from w v = 1 - v w), which normal ordering removes.
(4) A field carrying both chiralities: the anticommutator is <phi1, S_R phi2> + conj <phi1, S_L phi2>
(the left-handed part conjugated), not <phi1, S phi2>; read through Hestenes' projection onto
span{1, I sigma_3} (I sigma_3 commutes with every tower vector) it reproduces <phi1, S phi2> for both
chiralities at once.
"""
from fractions import Fraction as F

import GA
from GA import mul, add, sub, sc, gen, eq, is_zero, commutes, all_blades, QI
from tp_premise import premise

S4 = (1, -1, -1, -1)
I4 = {(0, 1, 2, 3): F(1)}
IS3 = {(1, 2): F(-1)}
G0 = gen(0)
KS = [(1, 0, 0, 1), (5, 3, 4, 0), (3, 2, 1, 2)]
NPL = 4 * len(KS)
SB = tuple(list(S4) + [1, -1] * NPL)
PX = [QI(F(3, 5), F(-4, 5)), QI(F(5, 13), F(12, 13)), QI(F(-8, 17), F(15, 17))]
PY = [QI(F(7, 25), F(24, 25)), QI(F(-3, 5), F(-4, 5)), QI(F(20, 29), F(21, 29))]
PHIS = [{(): F(1), (0, 1): F(2), (1, 3): F(-1), (0, 1, 2, 3): F(1, 2)},
        {(0, 2): F(1), (2, 3): F(3), (): F(-2)},
        {(1, 2): F(1), (0, 3): F(-1, 3), (0, 1, 2, 3): F(2)}]


def scl(c, x):
    return {b: c * v for b, v in x.items() if c * v != 0}


def blade(t):
    return {tuple(t): F(1)}


EVEN = [blade(b) for b in all_blades(4) if len(b) % 2 == 0]


def star(x, s):
    out = {}
    for b, c in x.items():
        g = len(b)
        sign = (-1) ** (g * (g - 1) // 2)
        for i in b:
            if s[i] == -1:
                sign = -sign
        out[b] = sign * c
    return {b: c for b, c in out.items() if c != 0}


def dag(phi, s=S4):
    return star(phi, s)


def alpha(phi, u):
    return mul(dag(phi), u, S4).get((), F(0))


def J(phi):
    return mul(phi, IS3, S4)


def cpair(phi, u):
    return QI(alpha(phi, u), alpha(J(phi), u))


def chi(eps, phi):
    return scl(F(1, 2), sub(phi, scl(F(eps), mul(mul(I4, phi, S4), IS3, S4))))


def rphase(u, z):
    return add(scl(z.re, u), scl(z.im, J(u)))


def kvec(k):
    return add(*[scl(F(k[m]), gen(m)) for m in range(4) if k[m] != 0])


def Lam(k, phi):
    return scl(F(1, 2 * k[0]), mul(mul(kvec(k), G0, S4), phi, S4))


def proj14(x):
    return {b: c for b, c in x.items() if tuple(i for i in b if i < 4) in ((), (0, 1, 2, 3))}


def projq(x):
    return {b: c for b, c in x.items() if tuple(i for i in b if i < 4) in ((), (1, 2))}


def cnum(z, eps, unit=None):
    return add(sc(z.re), scl(F(eps) * z.im, unit or I4))


def mat_rank(op):
    eb = [b for b in all_blades(4) if len(b) % 2 == 0]
    cols = [op(blade(b)) for b in eb]
    return GA.rank_of_vectors([[cols[j].get(eb[i], F(0)) for j in range(8)] for i in range(8)])


_F = {}


def spinor(k, eps):
    if (k, eps) not in _F:
        _F[(k, eps)] = next(c for c in (Lam(k, chi(eps, b)) for b in EVEN) if not is_zero(c))
    return _F[(k, eps)]


def plane(p):
    e_, f_ = 4 + 2 * p, 5 + 2 * p
    return add(scl(F(1, 2), gen(e_)), scl(F(1, 2), gen(f_))), add(scl(F(1, 2), gen(e_)), scl(F(-1, 2), gen(f_)))


PL = [plane(p) for p in range(NPL)]
# CAR sample: two distinct tower planes.
CAR_PLANE_A, CAR_PLANE_B = PL[0], PL[1]
# Projection control: chirality + and the first two test spinors.
CONTROL_EPS, CONTROL_PHI1, CONTROL_PHI2 = 1, PHIS[0], PHIS[1]


def field(phase, chiralities, antiparticles=True):
    out = {}
    for j, k in enumerate(KS):
        for ci, eps in enumerate(chiralities):
            f = spinor(k, eps)
            pp = 4 * j + 2 * ci
            out = add(out, mul(rphase(f, phase[j]), PL[pp][1], SB))
            if antiparticles:
                out = add(out, mul(rphase(f, phase[j].conj()), PL[pp + 1][0], SB))
    return out


def comp(phi, Psi, pr=proj14):
    return pr(mul(dag(phi, SB), Psi, SB))


def anti(a, b):
    return add(mul(a, b, SB), mul(b, a, SB))


def expected(phi1, phi2, chiralities, conj_for=()):
    tot = QI(0)
    for j, k in enumerate(KS):
        for eps in chiralities:
            f = spinor(k, eps)
            term = QI(0)
            for (px, py) in ((PX[j], PY[j]), (PX[j].conj(), PY[j].conj())):
                term = term + cpair(phi1, rphase(f, px)) * cpair(rphase(f, py), phi2)
            tot = tot + (term.conj() if eps in conj_for else term)
    return tot


def check_lambda_is_orthogonal_projector_onto_ker_k():
    for k in KS:
        kv = kvec(k)
        assert is_zero(mul(kv, kv, S4))
        for b in EVEN:
            lb = Lam(k, b)
            assert eq(Lam(k, lb), lb) and is_zero(mul(kv, lb, S4)) and eq(Lam(k, J(b)), J(lb))
            if is_zero(mul(kv, b, S4)):
                assert eq(lb, b)
            for e in (1, -1):
                assert eq(Lam(k, chi(e, b)), chi(e, Lam(k, b)))
        for b1 in EVEN:
            for b2 in EVEN:
                assert alpha(Lam(k, b1), b2) == alpha(b1, Lam(k, b2))
        assert mat_rank(lambda p: Lam(k, p)) == 4
        assert eq(scl(F(2 * k[0]), Lam(k, sc(1))), mul(kv, G0, S4))
        for eps in (1, -1):
            f = spinor(k, eps)
            a_ = alpha(f, f)
            assert a_ != 0
            for phi in EVEN + PHIS:
                assert eq(rphase(f, cpair(f, phi)), scl(a_, Lam(k, chi(eps, phi))))
            assert mat_rank(lambda p, k=k, eps=eps: Lam(k, chi(eps, p))) == 2


def check_field_anticommutator_is_local_kernel():
    premise("field-theory.imported-tower-limit")
    v0, w0 = CAR_PLANE_A
    v1, w1 = CAR_PLANE_B
    assert eq(anti(v0, w0), sc(1)) and is_zero(anti(v0, w1)) and is_zero(mul(v0, v0, SB))
    for eps in (1, -1):
        PsiX, PsiY = field(PX, (eps,)), field(PY, (eps,))
        for phi1 in PHIS:
            for phi2 in PHIS:
                A = anti(comp(phi1, PsiX), star(comp(phi2, PsiY), SB))
                assert all(max(b) < len(S4) for b in A if b)          # no tower generator in A
                assert eq(A, cnum(expected(phi1, phi2, (eps,)), eps))
                tot = QI(0)
                for j, k in enumerate(KS):
                    cosv = (PX[j] * PY[j].conj()).re
                    f = spinor(k, eps)
                    tot = tot + QI(2 * alpha(f, f) * cosv) * cpair(phi1, Lam(k, chi(eps, phi2)))
                assert tot == expected(phi1, phi2, (eps,))
    PsiX, PsiY = field(PX, (CONTROL_EPS,)), field(PY, (CONTROL_EPS,))
    raw = anti(mul(dag(CONTROL_PHI1, SB), PsiX, SB), star(mul(dag(CONTROL_PHI2, SB), PsiY, SB), SB))
    assert not eq(proj14(raw), raw)              # without the projection other ground components remain


def check_bilinears_are_second_quantised_operators():
    premise("field-theory.imported-tower-limit")
    for eps in (1, -1):
        for b in EVEN:
            u = chi(eps, b)
            assert eq(chi(eps, u), u)
            if is_zero(u):
                continue
            assert eq(mul(I4, u, S4), scl(F(eps), mul(u, IS3, S4)))
            for phi in EVEN + PHIS:
                assert eq(proj14(mul(dag(phi), u, S4)), cnum(cpair(phi, u), eps))
    nonchiral = add(chi(1, blade(())), chi(-1, blade((0, 1))))
    for e in (1, -1):
        assert any(not eq(proj14(mul(dag(phi), nonchiral, S4)), cnum(cpair(phi, nonchiral), e))
                   for phi in EVEN + PHIS)
    Psi_p = field(PX, (1,), antiparticles=False)
    for M in (sc(1), blade((0, 1)), blade((1, 2))):
        lhs = proj14(mul(mul(star(Psi_p, SB), M, SB), Psi_p, SB))
        rhs = {}
        for c, kc in enumerate(KS):
            uc = rphase(spinor(kc, 1), PX[c])
            for d, kd in enumerate(KS):
                ud = rphase(spinor(kd, 1), PX[d])
                rhs = add(rhs, mul(cnum(cpair(uc, mul(M, ud, S4)), 1), mul(PL[4 * c][0], PL[4 * d][1], SB), SB))
        assert eq(lhs, rhs)
    # with antiparticles: proj(Psi^* Psi) = sum_cd <x_c, y_d> X_c^* Y_d over particle (a = w, a^* = v) and
    # antiparticle (b^* = v) parts, with the antiparticle bilinear in the order b_c b_d^*; normal ordering
    # b_c b_d^* = delta_cd - b_d^* b_c leaves the c-number sum_c <vm_c, vm_c> = sum_c alpha(f_c, f_c) != 0
    Psi = field(PX, (1,))
    full = proj14(mul(star(Psi, SB), Psi, SB))
    parts = []
    for j, k in enumerate(KS):
        f = spinor(k, 1)
        parts.append((rphase(f, PX[j]), PL[4 * j][0], PL[4 * j][1]))                 # (u, a^*, a)
        parts.append((rphase(f, PX[j].conj()), PL[4 * j + 1][1], PL[4 * j + 1][0]))  # (vm, b, b^*)
    expansion = {}
    for xc, Xs, _ in parts:
        for yd, _, Y in parts:
            expansion = add(expansion, mul(cnum(cpair(xc, yd), 1), mul(Xs, Y, SB), SB))
    assert eq(full, expansion)
    normal = {}
    for c, (xc, Xs, _) in enumerate(parts):
        for d, (yd, _, Y) in enumerate(parts):
            if c % 2 == 1 and d % 2 == 1:
                bdag_d, b_c = parts[d][2], parts[c][1]
                term = scl(F(-1), mul(bdag_d, b_c, SB))                          # :b_c b_d^*: = -b_d^* b_c
            else:
                term = mul(Xs, Y, SB)
            normal = add(normal, mul(cnum(cpair(xc, yd), 1), term, SB))
    cnumber = sum((alpha(spinor(k, 1), spinor(k, 1)) for k in KS), F(0))
    assert cnumber != 0 and eq(sub(full, normal), sc(cnumber))


def check_mixed_chirality_split_forced_by_i_equals_I4():
    premise("field-theory.imported-tower-limit")
    PsiX, PsiY = field(PX, (1, -1)), field(PY, (1, -1))
    bad = False
    for phi1 in PHIS:
        for phi2 in PHIS:
            A = anti(comp(phi1, PsiX), star(comp(phi2, PsiY), SB))
            if not eq(A, cnum(expected(phi1, phi2, (1, -1)), 1)):
                bad = True
            assert eq(A, cnum(expected(phi1, phi2, (1, -1), conj_for=(-1,)), 1))
    assert bad
    assert all(commutes(IS3, gen(i), SB) for i in range(4, 4 + 2 * NPL))
    ok = {}
    for sgn in (1, -1):
        ok[sgn] = all(eq(anti(comp(p1, PsiX, projq), star(comp(p2, PsiY, projq), SB)),
                         cnum(expected(p1, p2, (1, -1)), sgn, IS3)) for p1 in PHIS for p2 in PHIS)
    assert ok[1] != ok[-1] and (ok[1] or ok[-1])

field-theory.twistor-attachment:
"""field-theory.twistor-attachment: exact checks of the finite core.

(1) The oscillator model of the palatial storey (premise: the palatial algebra is realised on
polynomials): operators on polynomials in y1..y4, Z = (y1, y2, d3, d4), Zbar = (-d1, -d2, y3, y4).
The relations [Z^a, Zbar_b] = delta_ab hold on all monomials of degree <= 3; in the Fock inner product
Zbar_a = Sigma_aa (Z^a)^dagger with Sigma = diag(-1, -1, 1, 1), the reversion form h on CS of
signature (2,2). With q(M) = sum M_ba (Z^a Zbar_b + Zbar_b Z^a)/2, helicity q(1)/2 = (N_b - N_a)/2
and the conformal energy q(Sigma)/2 = (N_a + N_b)/2 + 1, the palatial quadratic of h, on all monomials
of degree <= 4. Counting monomials: the helicity-s module has energies |s| + 1 + n with multiplicity
(n + 1)(n + 2|s| + 1) for 2s = -4..4, n <= 4, and E >= |s| + 1 on every monomial (positive energy).
(2) The sixteen q(E_ab), a basis of u(2,2)_C, commute with helicity on all monomials of degree <= 3,
change the energy only by -1, 0, +1 and keep every image in the positive-energy Fock module, so each
fixed-helicity module is preserved.
(3) Spin-statistics on the attachment (premise: the Penrose transform's kernels and the Jost-point
theorem): in the chart M^{BA'} the helicity kernels chi^{A'_1}..chi^{A'_m}/D^{m+1} (D = det M,
chi^{A'} = mu_B M^{BA'}) solve the zero-rest-mass equation for 2s = m = 1, 2 (s = 0: 1/D solves the
wave equation), the epsilon contraction does not vanish (control); under x -> -x the kernel numerator
picks up (-1)^{2s} and D is even, and at the spacelike point x = (1, 2, 1, 1) (det M = x^2 = -5)
W(-x) = (-1)^{2s} W(x) != 0 for 2s = 0..4: a CAR lift is local exactly for odd 2s, which the
series' fermions (2s = 1) satisfy.
That the tower's floors are energy cut-offs rather than regions is an interpretation with no finite
content beyond (1) and (2), and is not checked.
"""
from fractions import Fraction as F
from itertools import product

from GA import QI
from tp_premise import premise

NV = 4
SIG = [F(-1), F(-1), F(1), F(1)]
MU = [F(2), F(3)]
XPT = (F(1), F(2), F(1), F(1))


class Poly(object):
    def __init__(self, d=None, n=4):
        self.n = n
        self.d = {k: v for k, v in (d or {}).items() if v != 0}

    @staticmethod
    def var(i, n=4):
        e = [0] * n
        e[i] = 1
        return Poly({tuple(e): F(1)}, n)

    @staticmethod
    def const(c, n=4):
        return Poly({tuple([0] * n): c}, n)

    def __add__(self, o):
        d = dict(self.d)
        for k, v in o.d.items():
            d[k] = d.get(k, F(0)) + v
        return Poly(d, self.n)

    def __neg__(self):
        return Poly({k: -v for k, v in self.d.items()}, self.n)

    def __sub__(self, o):
        return self + (-o)

    def __mul__(self, o):
        if not isinstance(o, Poly):
            return Poly({k: o * v for k, v in self.d.items()}, self.n)
        d = {}
        for k1, v1 in self.d.items():
            for k2, v2 in o.d.items():
                k = tuple(a + b for a, b in zip(k1, k2))
                d[k] = d.get(k, F(0)) + v1 * v2
        return Poly(d, self.n)

    def deriv(self, i):
        d = {}
        for k, v in self.d.items():
            if k[i] > 0:
                kk = list(k)
                kk[i] -= 1
                d[tuple(kk)] = d.get(tuple(kk), F(0)) + v * k[i]
        return Poly(d, self.n)

    def is_zero(self):
        return not self.d

    def ev(self, pt):
        tot = QI(0)
        for k, v in self.d.items():
            t = QI(v)
            for x, e in zip(pt, k):
                for _ in range(e):
                    t = t * x
            tot = tot + t
        return tot

    def subst_neg(self):
        return Poly({k: v * (-1) ** sum(k) for k, v in self.d.items()}, self.n)


def mono_basis(deg):
    return [Poly({e: F(1)}, NV) for e in product(range(deg + 1), repeat=NV) if sum(e) <= deg]


def op_Z(a):
    return (lambda p: Poly.var(a, NV) * p) if a < 2 else (lambda p: p.deriv(a))


def op_Zb(b):
    return (lambda p: -p.deriv(b)) if b < 2 else (lambda p: Poly.var(b, NV) * p)


def fock_ip(p, q):
    tot = F(0)
    for k, v in p.d.items():
        if k in q.d:
            f = 1
            for e in k:
                for j in range(2, e + 1):
                    f *= j
            tot += v * q.d[k] * f
    return tot


def qM(Mm):
    def f(p):
        tot = Poly(n=NV)
        for a in range(4):
            for b in range(4):
                c = Mm[b][a]
                if c != 0:
                    tot = tot + (op_Z(a)(op_Zb(b)(p)) + op_Zb(b)(op_Z(a)(p))) * (c / 2)
        return tot
    return f


def energy(k):
    return F(sum(k), 2) + 1


def check_oscillator_module_spectrum_and_twistor_form():
    premise("field-theory.imported-statistics-no-go-palatial-algebra")
    b3 = mono_basis(3)
    for a in range(4):
        for b in range(4):
            for p in b3:
                c = op_Z(a)(op_Zb(b)(p)) - op_Zb(b)(op_Z(a)(p))
                assert (c - (p if a == b else Poly(n=NV))).is_zero()
                assert (op_Z(a)(op_Z(b)(p)) - op_Z(b)(op_Z(a)(p))).is_zero()
        for p in b3:
            for q in b3:
                assert fock_ip(p, op_Zb(a)(q)) == SIG[a] * fock_ip(op_Z(a)(p), q)
    assert sum(1 for s in SIG if s > 0) == 2 and sum(1 for s in SIG if s < 0) == 2
    Id = [[F(int(i == j)) for j in range(4)] for i in range(4)]
    SigM = [[SIG[i] if i == j else F(0) for j in range(4)] for i in range(4)]
    qid, qsig = qM(Id), qM(SigM)
    for p in mono_basis(4):
        (k, _), = p.d.items()
        Na, Nb = k[0] + k[1], k[2] + k[3]
        assert (qid(p) * F(1, 2) - p * F(Nb - Na, 2)).is_zero()
        assert (qsig(p) * F(1, 2) - p * (F(Na + Nb, 2) + 1)).is_zero()
    tally = {}
    for e in product(range(13), repeat=4):
        Na, Nb = e[0] + e[1], e[2] + e[3]
        if Na + Nb <= 12:
            key = (Nb - Na, F(Na + Nb, 2) + 1)
            tally[key] = tally.get(key, 0) + 1
    for twos in range(-4, 5):
        for n in range(0, 5):
            assert tally.get((twos, F(abs(twos), 2) + 1 + n), 0) == (n + 1) * (n + abs(twos) + 1)
        assert tally.get((twos, F(abs(twos), 2)), 0) == 0          # nothing below |s| + 1
    for e in product(range(7), repeat=4):
        Na, Nb = e[0] + e[1], e[2] + e[3]
        assert energy(e) >= F(abs(Nb - Na), 2) + 1


def check_u22_preserves_positive_energy_helicity_modules():
    premise("field-theory.imported-statistics-no-go-palatial-algebra")
    qid = qM([[F(int(i == j)) for j in range(4)] for i in range(4)])
    moves = set()
    gens = 0
    for a in range(4):
        for b in range(4):
            qe = qM([[F(int(i == b and j == a)) for j in range(4)] for i in range(4)])
            gens += 1
            for pp in mono_basis(3):
                (k0, _), = pp.d.items()
                img = qe(pp)
                assert (qid(img) - qe(qid(pp))).is_zero()
                for k1 in img.d:
                    moves.add(energy(k1) - energy(k0))
                    assert energy(k1) >= F(abs(k1[2] + k1[3] - k1[0] - k1[1]), 2) + 1
    assert gens == 16 and moves == {F(-1), F(0), F(1)}


def check_kernels_exchange_parity_is_spin_statistics():
    premise("field-theory.imported-standard-field-theory")
    m00, m01, m10, m11 = (Poly.var(i) for i in range(4))
    Mv = [[m00, m01], [m10, m11]]
    idx = [[0, 1], [2, 3]]
    D = m00 * m11 - m01 * m10
    chi = [Mv[0][a] * MU[0] + Mv[1][a] * MU[1] for a in range(2)]
    lap = ((D.deriv(0) * D.deriv(3)) * F(2) - D * D.deriv(0).deriv(3)) - \
          ((D.deriv(1) * D.deriv(2)) * F(2) - D * D.deriv(1).deriv(2))
    assert lap.is_zero()
    for m in (1, 2):
        for contraction in ("trace", "eps"):
            outs = []
            for B in range(2):
                for rest in product(range(2), repeat=m - 1):
                    Pi = Poly.const(F(1))
                    for c in rest:
                        Pi = Pi * chi[c]
                    tot = Poly()
                    for A in range(2):
                        if contraction == "trace":
                            dv, sgn = idx[B][A], F(1)
                        else:
                            dv, sgn = idx[B][1 - A], F(1) if A == 0 else F(-1)
                        num = chi[A] * Pi
                        tot = tot + (num.deriv(dv) * D - (num * D.deriv(dv)) * F(m + 1)) * sgn
                    outs.append(tot)
            if contraction == "trace":
                assert all(p.is_zero() for p in outs)
            else:
                assert any(not p.is_zero() for p in outs)
    x0, x1, x2, x3 = XPT
    pt = [QI(x0 + x3), QI(x1, -x2), QI(x1, x2), QI(x0 - x3)]
    Dv = D.ev(pt)
    assert Dv == QI(-5)
    assert (D.subst_neg() - D).is_zero()
    for m in range(0, 5):
        num = Poly.const(F(1))
        for _ in range(m):
            num = num * chi[0]
        assert (num.subst_neg() - num * F((-1) ** m)).is_zero()
        den = QI(1)
        for _ in range(m + 1):
            den = den * Dv
        Wx = num.ev(pt) / den
        Wmx = num.ev([-p for p in pt]) / den
        assert Wx != 0 and Wmx == Wx * ((-1) ** m)
        assert (Wmx == -Wx) == (m % 2 == 1)          # odd 2s: the kernel is odd, the CAR lift is local
